TradeFileProcessor processor;
try {
    processor = new TradeFileProcessor("/trades/batch.csv");
} catch (IOException e) {
    // processor is still null! The new expression NEVER returned.
    // Partially-constructed object → unreachable → GC'd.
}
// processor == null here if constructor threw.

// ═══ RESOURCE LEAK IN CONSTRUCTOR ═══
public class TradeFileProcessor {
    private final BufferedReader reader;
    private final Connection connection;

    // (Avoid) LEAKY CONSTRUCTOR:
    public TradeFileProcessor(String filePath) throws IOException, SQLException {
        this.reader = new BufferedReader(new FileReader(filePath));  // opened!
        this.connection = DriverManager.getConnection(DB_URL);       // opened!
        // If THIS line throws → reader and connection are LEAKED!
        validateSchema(this.connection);  // throws SQLException
        // reader: opened, never closed. connection: opened, never closed.
        // Nobody has a reference to close them — the object was never returned!
    }
}

// ═══ FIX 1: try-catch-finally IN constructor ═══
public class TradeFileProcessor {
    private final BufferedReader reader;
    private final Connection connection;

    public TradeFileProcessor(String filePath) throws IOException, SQLException {
        BufferedReader tempReader = null;
        Connection tempConn = null;
        try {
            tempReader = new BufferedReader(new FileReader(filePath));
            tempConn = DriverManager.getConnection(DB_URL);
            validateSchema(tempConn);  // might throw
            this.reader = tempReader;
            this.connection = tempConn;
        } catch (Exception e) {
            // Cleanup everything opened so far:
            if (tempReader != null) try { tempReader.close(); } catch (IOException ex) { }
            if (tempConn != null) try { tempConn.close(); } catch (SQLException ex) { }
            throw e;  // rethrow after cleanup
        }
    }
}

// ═══ FIX 2: static factory with try-with-resources ═══
public class TradeFileProcessor implements AutoCloseable {
    private final BufferedReader reader;
    private final Connection connection;

    private TradeFileProcessor(BufferedReader reader, Connection connection) {
        this.reader = reader;
        this.connection = connection;
    }

    public static TradeFileProcessor create(String filePath) throws IOException, SQLException {
        BufferedReader reader = new BufferedReader(new FileReader(filePath));
        try {
            Connection conn = DriverManager.getConnection(DB_URL);
            try {
                validateSchema(conn);
                return new TradeFileProcessor(reader, conn);
            } catch (Exception e) {
                conn.close();
                throw e;
            }
        } catch (Exception e) {
            reader.close();
            throw e;
        }
    }

    @Override
    public void close() throws Exception {
        reader.close();
        connection.close();
    }
}
