// ─── File: src/test/java/com/bank/constructor/ConstructorExceptionTest.java ───
package com.bank.constructor;

import org.junit.jupiter.api.Test;
import java.util.ArrayList;
import java.util.List;
import static org.assertj.core.api.Assertions.*;

class ConstructorExceptionTest {

    // Simulates a resource that tracks open/close
    static class FakeResource implements AutoCloseable {
        static final List<String> LOG = new ArrayList<>();
        private final String name;

        FakeResource(String name) {
            this.name = name;
            LOG.add("OPEN:" + name);
        }

        @Override
        public void close() {
            LOG.add("CLOSE:" + name);
        }
    }

    // ═══ LEAKY constructor: resource never closed ═══
    static class LeakyProcessor {
        private final FakeResource fileHandle;
        private final FakeResource dbConnection;

        LeakyProcessor() {
            this.fileHandle = new FakeResource("file");       // opened!
            this.dbConnection = new FakeResource("db");       // opened!
            throw new RuntimeException("Schema validation failed");
            // fileHandle + dbConnection: opened but NEVER closed!
        }
    }

    // ═══ SAFE constructor: cleanup on failure ═══
    static class SafeProcessor {
        private final FakeResource fileHandle;
        private final FakeResource dbConnection;

        SafeProcessor() {
            FakeResource tempFile = null;
            FakeResource tempDb = null;
            try {
                tempFile = new FakeResource("file");
                tempDb = new FakeResource("db");
                // Simulate failure:
                if (true) throw new RuntimeException("Schema validation failed");
                this.fileHandle = tempFile;
                this.dbConnection = tempDb;
            } catch (Exception e) {
                if (tempDb != null) tempDb.close();    // cleanup!
                if (tempFile != null) tempFile.close(); // cleanup!
                throw e;
            }
        }
    }

    @Test
    void leakyConstructor_resourcesNeverClosed() {
        FakeResource.LOG.clear();
        assertThatThrownBy(LeakyProcessor::new).hasMessageContaining("Schema");

        // Resources opened but NEVER closed!
        assertThat(FakeResource.LOG).containsExactly("OPEN:file", "OPEN:db");
        // No CLOSE entries! LEAKED!
    }

    @Test
    void safeConstructor_resourcesCleaned() {
        FakeResource.LOG.clear();
        assertThatThrownBy(SafeProcessor::new).hasMessageContaining("Schema");

        // Resources opened AND closed on failure!
        assertThat(FakeResource.LOG).containsExactly(
            "OPEN:file", "OPEN:db", "CLOSE:db", "CLOSE:file");
        // Both closed! No leak!
    }

    @Test
    void objectNeverAssigned() {
        LeakyProcessor[] holder = { null };
        try {
            holder[0] = new LeakyProcessor();
        } catch (RuntimeException e) {
            // constructor threw — assignment never happened!
        }
        assertThat(holder[0]).isNull();
        // Object NEVER returned. Reference stays null.
    }
}
